/*
 * node_modules/net/lib/http.js — request/response framing.
 *
 * Split out of index.js the way Node keeps its http internals in lib/:
 * parsing, status text and the response writer live here, while index.js
 * stays the public entry point.
 */

export const STATUS_TEXT = {
    200: 'OK', 201: 'Created', 204: 'No Content',
    301: 'Moved Permanently', 302: 'Found', 304: 'Not Modified',
    400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden',
    404: 'Not Found', 405: 'Method Not Allowed', 409: 'Conflict',
    418: "I'm a teapot",
    500: 'Internal Server Error', 501: 'Not Implemented',
    502: 'Bad Gateway', 503: 'Service Unavailable',
};

export function reason(code) {
    return STATUS_TEXT[code] || 'Unknown';
}

/* UTF-8 byte length of a JS string (surrogate pairs count as 4 bytes).
 * HTTP content-length is a byte count; a naive body.length (UTF-16 code
 * units) makes the client stop reading early and silently truncates any
 * response containing non-ASCII characters. */
export function utf8Len(s) {
    let n = 0;
    for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i);
        if (c < 0x80) n += 1;
        else if (c < 0x800) n += 2;
        else if (c >= 0xD800 && c <= 0xDBFF) { n += 4; i++; }
        else n += 3;
    }
    return n;
}

export function parseRequest(raw) {
    const sep = raw.indexOf('\r\n\r\n');
    const head = sep >= 0 ? raw.slice(0, sep) : raw;
    const body = sep >= 0 ? raw.slice(sep + 4) : '';

    const lines = head.split('\r\n');
    const [method, target = '/'] = (lines[0] || '').split(/\s+/);

    const headers = Object.create(null);
    for (let i = 1; i < lines.length; i++) {
        const m = /^([^:\s]+):\s*(.*)$/.exec(lines[i]);
        if (m) headers[m[1].toLowerCase()] = m[2].trim();
    }

    const qIdx = target.indexOf('?');
    const path = qIdx >= 0 ? target.slice(0, qIdx) : target;
    const query = Object.create(null);
    if (qIdx >= 0) {
        for (const pair of target.slice(qIdx + 1).split('&')) {
            if (!pair) continue;
            const eq = pair.indexOf('=');
            const k = eq >= 0 ? pair.slice(0, eq) : pair;
            const v = eq >= 0 ? pair.slice(eq + 1) : '';
            query[decodeURIComponent(k)] = decodeURIComponent(v);
        }
    }

    return { method, url: target, path, query, headers, body };
}

export function makeResponse(write, conn) {
    let statusCode = 200;
    const headers = Object.create(null);
    let ended = false;

    const res = {
        get statusCode() { return statusCode; },
        set statusCode(v) { statusCode = v; },

        get statusMessage() { return reason(statusCode); },

        setHeader(name, value) {
            headers[String(name).toLowerCase()] = String(value);
        },

        writeHead(code, extra) {
            statusCode = code;
            if (extra) Object.assign(headers, extra);
        },

        status(code) {
            statusCode = code;
            return res;
        },

        get(k) { return headers[String(k).toLowerCase()]; },

        set(name, value) {
            headers[String(name).toLowerCase()] = String(value);
            return res;
        },

        type(contentType) {
            headers['content-type'] = contentType;
            return res;
        },

        attachment(name) {
            headers['content-disposition'] = 'attachment' +
                (name ? '; filename="' + name + '"' : '');
            return res;
        },

        redirect(code, url) {
            if (url === undefined) { url = code; code = 302; }
            headers['location'] = String(url);
            return res.status(code).end('');
        },

        json(obj) {
            return res.end(JSON.stringify(obj), 'application/json; charset=utf-8');
        },

        send(body) {
            return res.end(body);
        },

        end(body, contentType) {
            if (ended) return;
            ended = true;
            if (typeof body === 'object' && body !== null) {
                body = JSON.stringify(body);
                contentType = contentType || 'application/json; charset=utf-8';
            }
            body = body === undefined ? '' : String(body);
            if (!headers['content-length'] && body.length > 0)
                headers['content-length'] = String(utf8Len(body));
            if (contentType && !headers['content-type'])
                headers['content-type'] = contentType;

            const head = 'HTTP/1.1 ' + statusCode + ' ' + reason(statusCode) + '\r\n' +
                Object.keys(headers).map(k => k + ': ' + headers[k]).join('\r\n') +
                '\r\n\r\n';
            write(conn, head + body);
        },
    };
    return res;
}
